/**
 * How delivery works: the facts as icon cards, then the zones with their time and the order that ships free.
 * Axes: layout (full: facts over zone cards, facts: the facts only, split: the facts beside a list of zones),
 * tone, density.
 */
import { type ReactNode } from "react";
import { Badge } from "../primitives/badge/badge";
import { Box } from "../primitives/box/box";
import { Grid } from "../primitives/grid/grid";
import { Group } from "../primitives/group/group";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import { Stack } from "../primitives/stack/stack";
import { Text } from "../primitives/text/text";
import { Title } from "../primitives/title/title";
import { SectionFrame } from "../components/section-frame";
import { cn, fmtMoney, tpl } from "../utils";
import type { DeliveryLabels } from "./delivery-info.types";
import type { Feature } from "./feature-grid.types";
import type { Zone } from "./zone-table.types";

export type DeliveryInfoProps = {
  id: string;
  title: string;
  lead?: string;
  facts: Feature[];
  zones: Zone[];
  labels: DeliveryLabels;
  layout?: "full" | "facts" | "split";
  tone?: "default" | "muted";
  density?: "default" | "compact";
};

export function DeliveryInfo({
  id,
  title,
  lead = "",
  facts,
  zones,
  labels,
  layout = "full",
  tone = "default",
  density = "default",
}: DeliveryInfoProps) {
  return (
    <SectionFrame id={id} title={title} lead={lead} tone={tone} density={density}>
      <Box
        className={cn(
          "grid grid-cols-1 gap-8",
          (((layout as string) === "split") ? "items-start md:grid-cols-2" : "")
        )}
      >
        <Grid cols={(((layout as string) === "split") ? "1-2" : "1-4")} className="gap-4" data-testid="facts">
          {(facts ?? []).map((f) => (
            <Stack key={f.id} gap="4" className="rounded bg-card inset-ring inset-ring-border p-6" data-testid="fact">
              <Box className="flex size-10 shrink-0 items-center justify-center rounded bg-muted">
                <LucideIcon name={f.icon} size={20} />
              </Box>
              <Stack gap="2">
                <Text size="sm" weight="semibold">
                  {f.title}
                </Text>
                <Text size="sm" className="text-muted-foreground">
                  {f.text}
                </Text>
              </Stack>
            </Stack>
          ))}
        </Grid>
        {((layout as string) !== "facts") ? (
          <Stack gap="4" align="stretch">
            <Title as={3} size="lg" weight="bold">
              {labels.zones}
            </Title>
            <Box
              className={
                (layout as string) === "split" ? "flex flex-col gap-4"
                : "grid grid-cols-1 gap-4 md:grid-cols-3"
              }
            >
              {(zones ?? []).map((z) => (
                <Stack key={z.id}
                  gap="2"
                  className={
                    (layout as string) === "split" ? "border-b border-border pb-4"
                    : "rounded bg-card inset-ring inset-ring-border p-6"
                  }
                  data-testid="zone"
                >
                  <Group gap="4" align="baseline" justify="between">
                    <Text size="sm" weight="semibold">
                      {z.name}
                    </Text>
                    <Badge variant="secondary" size="default">
                      {z.time}
                    </Badge>
                  </Group>
                  <Text size="sm" className="text-muted-foreground">
                    {z.area}
                  </Text>
                  <Text size="sm" weight="medium">
                    {tpl(labels.freeFrom, fmtMoney(z.freeFrom, z.currency))}
                  </Text>
                </Stack>
              ))}
            </Box>
          </Stack>
        ) : null}
      </Box>
    </SectionFrame>
  );
}

